import React from 'react';
import '../styles/dashboard.css';

function StatCard({ title, count, icon }) {
  return (
    <div className="stat-card">
      <div className="stat-icon">{icon}</div>
      <div className="stat-info">
        <h4>{title}</h4>
        <p>{count}</p>
      </div>
    </div>
  );
}

export default StatCard;
